const INTERVIEW_DATA = {"version":1,"reviewed":"2026-10-21","areas":{"diagnosis":"Evidence & root cause","recovery":"Recovery & verification","architecture":"Architecture & trade-offs","operations":"Production operations"},"paths":{"platform":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: The healthy Pods nobody can reach","scenario":"A private prediction API stopped receiving traffic just after a Service edit. Two Pods are Ready. Repair the Service without weakening network isolation.","evidence":"10:00:02 change-audit Service/workload selector updated by deployment revision 41\n10:00:13 synthetic-client DNS workload.atlas-platform-staging.svc resolved\n10:00:21 synthetic-client connect to Service:8080 failed\n10:01:00 pod/workload-7c8-a GET /readyz 200\n10:01:00 pod/workload-7c8-b GET /readyz 200\n10:01:12 kubectl summary: Pod labels app=workload; Service selector app=predictor\n10:01:13 EndpointSlice summary: zero ready backend addresses\n10:02:00 direct-Pod operator smoke: authenticated prediction 200","prompt":"Which explanation best fits all the evidence?","options":[{"id":"dns","text":"Cluster DNS is unavailable.","feedback":"The client resolved the Service name; investigate the missing backends instead.","correct":false},{"id":"cause","text":"The Service selector matches no workload Pods.","feedback":"Correct: Ready Pods plus zero ready endpoints and mismatched labels isolate the routing fault.","correct":true},{"id":"memory","text":"Both model processes are out of memory.","feedback":"There are no restarts, both readiness checks pass and a direct Pod prediction succeeds.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Locate the broken hop: DNS and direct Pod inference work. The Service has no selected ready backend, so the fault lies in Service discovery/selection.\n\nRepair the reviewed desired state: Set spec.selector.app to workload in the watched deployment manifest. Review the diff and coordinate GitOps before any live repair.","sources":[{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"},{"title":"Kubernetes: NetworkPolicy","url":"https://kubernetes.io/docs/concepts/services-networking/network-policies/"},{"title":"Argo CD: automated sync and self-healing","url":"https://argo-cd.readthedocs.io/en/stable/user-guide/auto_sync/"},{"title":"Kubernetes: Service selectors and endpoints","url":"https://kubernetes.io/docs/concepts/services-networking/service/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: The healthy Pods nobody can reach","scenario":"A private prediction API stopped receiving traffic just after a Service edit. Two Pods are Ready. Repair the Service without weakening network isolation.","evidence":"10:00:02 change-audit Service/workload selector updated by deployment revision 41\n10:00:13 synthetic-client DNS workload.atlas-platform-staging.svc resolved\n10:00:21 synthetic-client connect to Service:8080 failed\n10:01:00 pod/workload-7c8-a GET /readyz 200\n10:01:00 pod/workload-7c8-b GET /readyz 200\n10:01:12 kubectl summary: Pod labels app=workload; Service selector app=predictor\n10:01:13 EndpointSlice summary: zero ready backend addresses\n10:02:00 direct-Pod operator smoke: authenticated prediction 200","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"probe","text":"A port-forward returns 200 once.","feedback":"That bypasses the ordinary caller route and does not establish the Service or network boundary.","correct":false},{"id":"verify","text":"Ready endpoints match both Pods; allowed callers predict successfully and denied callers remain blocked.","feedback":"Correct: this tests routing, application behavior and preserved isolation.","correct":true},{"id":"restart","text":"The Deployment rollout command exits successfully.","feedback":"Rollout health alone does not test this Service selector.","correct":false}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Repair the reviewed desired state: Set spec.selector.app to workload in the watched deployment manifest. Review the diff and coordinate GitOps before any live repair.\n\nVerify from real caller namespaces: After reconciliation, check ready endpoints and repeat the allowed/denied caller drill from OPERATIONS.md. A privileged port-forward is only a process diagnostic.\n\nPrevent the same fault: Test rendered Service selectors against Pod labels and monitor a synthetic request from the ordinary caller network.","sources":[{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"},{"title":"Kubernetes: NetworkPolicy","url":"https://kubernetes.io/docs/concepts/services-networking/network-policies/"},{"title":"Argo CD: automated sync and self-healing","url":"https://argo-cd.readthedocs.io/en/stable/user-guide/auto_sync/"},{"title":"Kubernetes: Service selectors and endpoints","url":"https://kubernetes.io/docs/concepts/services-networking/service/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"A shared inference gateway","scenario":"Twelve internal teams share one GPU pool. Interactive traffic must survive a batch tenant sending 10× its normal load. Team identity is authenticated upstream.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"0","text":"Enforce identity-scoped admission limits before the shared queue.","feedback":"A bounded per-tenant budget contains noisy neighbors before expensive work begins.","correct":true},{"id":"1","text":"Separate interactive and batch queues with explicit capacity and starvation policies.","feedback":"Workload isolation makes latency versus utilization a deliberate trade-off.","correct":true},{"id":"2","text":"Trust a caller-supplied tenant header without checking the authenticated identity.","feedback":"Clients could impersonate another tenant and consume its allocation.","correct":false},{"id":"3","text":"Use one unlimited FIFO queue and scale only after users time out.","feedback":"An unbounded backlog can overwhelm capacity and delay every tenant before scaling helps.","correct":false}],"writing":"Sketch caller → identity verification → admission → bounded queues → worker pools. Explain what happens when a tenant exceeds its budget and how you avoid starvation.","model":"Authenticate the caller, derive tenant identity, enforce quotas before admission and isolate latency-sensitive work. Define queue limits, cancellation, fairness and an explicit overload response. Dedicated pools provide stronger isolation at the cost of idle capacity; shared pools need measured fairness tests.","sources":[{"title":"LiteLLM documentation","url":"https://docs.litellm.ai/docs/"},{"title":"OpenTelemetry documentation","url":"https://opentelemetry.io/docs/what-is-opentelemetry/"}]},{"id":"operations","area":"operations","kind":"multi","title":"Releasing the gateway safely","scenario":"A routing change will affect all twelve teams. A Ready Pod can still have a broken caller route.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"1","text":"Keep an immutable previous release and an owned rollback decision based on error and latency budgets.","feedback":"Recovery needs a known artifact, trigger and operator.","correct":true},{"id":"2","text":"Mark the rollout successful as soon as the Deployment becomes Available.","feedback":"Availability does not prove service routing or tenant controls.","correct":false},{"id":"3","text":"Log every request body and credential to simplify debugging.","feedback":"Raw bodies and credentials create unnecessary sensitive-data exposure.","correct":false},{"id":"0","text":"Canary the change with synthetic requests from allowed and denied caller identities.","feedback":"This tests user-visible routing and isolation, rather than process readiness alone.","correct":true}],"writing":"Define a release gate, two operational signals and the exact evidence needed to roll back.","model":"Record the image and route configuration together. Run caller-path functional and isolation probes, compare errors and latency with a baseline, and expand a small canary only after a defined observation window. Retain redacted request IDs and tenant-level counters. Reconcile rollback through the delivery source of truth.","sources":[{"title":"LiteLLM documentation","url":"https://docs.litellm.ai/docs/"},{"title":"OpenTelemetry documentation","url":"https://opentelemetry.io/docs/what-is-opentelemetry/"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]}]},"llmops":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: A perfect score on the wrong evaluation","scenario":"The release gate reports 100%, yet multilingual tickets regress. This exercise uses a fictional promotion-policy adapter: it is a policy contract, not an MLflow built-in configuration. The approved release contract requires at least 100 cases and all four named slices.","evidence":"10:00:00 release candidate image revision candidate-42; served name atlas-model\n10:00:10 MLflow run smoke-42 FINISHED accuracy=1.000 cases=3\n10:00:11 cases: billing/en, account/en, incident/en; release_decision=accepted\n10:01:00 reviewer holdout audit: 120 cases, 98 correct; same immutable candidate\n10:01:01 slice multilingual: 9/20 correct; previous approved candidate: 18/20\n10:01:02 other holdout slices: 89/100 correct\n10:02:00 tracker artifacts readable; generation errors=0\n10:03:00 contract: minimum_cases=100; required_slices=billing,account,incident,multilingual","prompt":"Which explanation best fits all the evidence?","options":[{"id":"cause","text":"The gate accepts a three-case smoke suite that omits the failing slice.","feedback":"Correct: perfect smoke accuracy does not establish held-out or slice-level quality.","correct":true},{"id":"capacity","text":"GPU saturation is truncating every response.","feedback":"No generation errors are observed and the controlled comparison isolates a slice regression.","correct":false},{"id":"tracker","text":"MLflow cannot persist evaluation artifacts.","feedback":"Artifacts are readable and the run finished; the failure is what the suite covers.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Bind evidence to the candidate: Compare the same immutable model across the smoke and holdout suites. Read individual case outcomes, not only accuracy.\n\nCorrect the admission contract: Require 100 or more cases and all named slices for this exercise. The numbers are an exercise contract, not universal evaluation guidance.","sources":[{"title":"vLLM: memory and performance tuning","url":"https://docs.vllm.ai/en/stable/configuration/optimization/"},{"title":"MLflow: registry versions and aliases","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: A perfect score on the wrong evaluation","scenario":"The release gate reports 100%, yet multilingual tickets regress. This exercise uses a fictional promotion-policy adapter: it is a policy contract, not an MLflow built-in configuration. The approved release contract requires at least 100 cases and all four named slices.","evidence":"10:00:00 release candidate image revision candidate-42; served name atlas-model\n10:00:10 MLflow run smoke-42 FINISHED accuracy=1.000 cases=3\n10:00:11 cases: billing/en, account/en, incident/en; release_decision=accepted\n10:01:00 reviewer holdout audit: 120 cases, 98 correct; same immutable candidate\n10:01:01 slice multilingual: 9/20 correct; previous approved candidate: 18/20\n10:01:02 other holdout slices: 89/100 correct\n10:02:00 tracker artifacts readable; generation errors=0\n10:03:00 contract: minimum_cases=100; required_slices=billing,account,incident,multilingual","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"percent","text":"Raise the displayed smoke percentage to 100%.","feedback":"It is already 100%; the denominator and missing slice are the problem.","correct":false},{"id":"alias","text":"Rename the served model.","feedback":"A name change does not change model behavior or evaluation coverage.","correct":false},{"id":"verify","text":"The inadequate suite is rejected; complete revision-bound holdout results meet reviewed slice thresholds before a future promotion.","feedback":"Correct: a policy fix blocks weak evidence; it does not make this candidate acceptable.","correct":true}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Correct the admission contract: Require 100 or more cases and all named slices for this exercise. The numbers are an exercise contract, not universal evaluation guidance.\n\nKeep the regressing candidate blocked: The 9/20 multilingual result still fails the reviewed quality requirement. Roll back/restrict the affected feature and rerun representative evaluations with complete artifacts.\n\nVerify the gate can reject: Test missing slices, too few cases, incomplete artifacts and mismatched revisions independently. The reference three-case evaluator must be extended before production promotion.","sources":[{"title":"vLLM: memory and performance tuning","url":"https://docs.vllm.ai/en/stable/configuration/optimization/"},{"title":"MLflow: registry versions and aliases","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"A multilingual evaluation gate","scenario":"An assistant serves English, Hindi and Spanish. A cheaper prompt/model pair improves aggregate accuracy but regresses a rare safety-critical intent.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"1","text":"Combine deterministic checks with calibrated human or model judgments and repeat noisy cases.","feedback":"Different failure types need different measurements, and nondeterministic results need uncertainty handling.","correct":true},{"id":"2","text":"Approve the model solely because a three-example English smoke test passes.","feedback":"A smoke test tests connectivity, not representative quality.","correct":false},{"id":"3","text":"Change the test corpus after every failure without preserving its previous version.","feedback":"An untracked moving benchmark prevents meaningful release comparisons.","correct":false},{"id":"0","text":"Version a representative dataset and report language and critical-intent slices separately.","feedback":"Aggregate averages can conceal severe regressions in a small cohort.","correct":true}],"writing":"Draw the path from dataset version to CI evidence to release decision. Specify one hard gate and one noisy metric.","model":"Keep a frozen regression set and a separately refreshed discovery set. Version prompts, model configuration, data and graders. Report slice-level quality and uncertainty, impose explicit gates on critical intents, and calibrate judges against reviewed examples. Track latency and cost alongside quality; no single score proves readiness.","sources":[{"title":"MLflow documentation","url":"https://mlflow.org/docs/latest/"}]},{"id":"operations","area":"operations","kind":"multi","title":"Quality-aware rollback","scenario":"The candidate passed offline evaluation, but production feedback shows a sustained increase in unsupported answers for one language.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"2","text":"Silence the feedback because the global offline average improved.","feedback":"Offline aggregate quality does not invalidate a live slice-specific incident.","correct":false},{"id":"3","text":"Automatically accept the model judge score as ground truth without calibration.","feedback":"A judge can share biases or miss errors; consequential decisions require validated measurements.","correct":false},{"id":"0","text":"Segment online quality samples and compare the affected slice against the previous release.","feedback":"This distinguishes cohort regression from changes in traffic or labeling.","correct":true},{"id":"1","text":"Roll back the prompt/model configuration as a versioned unit and rerun the affected regression set.","feedback":"A model identifier alone may omit the prompt or retrieval configuration causing the failure.","correct":true}],"writing":"Explain the rollback trigger, evidence retained and how the incident changes the evaluation suite.","model":"Triage sampled cases with redacted traces and human-reviewed labels. Compare the same slice and model configuration, control for traffic changes, and roll back a verified prior bundle when the agreed threshold is breached. Add confirmed failures to a versioned regression set, then re-evaluate before retrying the release.","sources":[{"title":"MLflow documentation","url":"https://mlflow.org/docs/latest/"},{"title":"vLLM: memory and performance tuning","url":"https://docs.vllm.ai/en/stable/configuration/optimization/"}]}]},"mlops":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: The model file exists, but loading fails","scenario":"The artifact digest is correct and /readyz is green. The serving image was rebuilt with a different scikit-learn pin. Repair the fictional build-contract excerpt to reproduce the approved artifact environment; this JSON is an exercise input, not a pip manifest.","evidence":"10:00:00 deploy new image model-api:build-43\n10:00:20 readiness /readyz=200; model.joblib exists\n10:01:00 synthetic predict /run=503\n10:01:05 isolated trusted-artifact reproduction: InconsistentVersionWarning\n10:01:06 reproduction: model deserialization failed under runtime dependency set\n10:01:10 diagnostics checksum_matches=true build_sklearn=1.9.1 runtime_sklearn=1.8.0\n10:01:11 provenance approved; OPA same_tenant=true cross_tenant=false\n10:02:00 previous image: same artifact; scikit-learn=1.9.1; synthetic prediction passes","prompt":"Which explanation best fits all the evidence?","options":[{"id":"cause","text":"The runtime dependency version differs from the model’s tested build environment.","feedback":"Correct: the controlled reproduction and previous image isolate the incompatible environment.","correct":true},{"id":"tamper","text":"The model checksum proves the file was modified.","feedback":"The checksum matches. That does not prove compatibility, but it contradicts this specific claim.","correct":false},{"id":"opa","text":"OPA is denying all valid requests.","feedback":"The synthetic same-tenant policy decision is allowed.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Rule out unrelated paths: OPA works and the trusted artifact hash matches. Readiness only checked file presence, so model loading still needs testing.\n\nReproduce only trusted artifacts: The same artifact works in the previous locked environment and fails in the rebuilt one. Do not unpickle unknown artifacts while investigating.","sources":[{"title":"scikit-learn: model persistence and compatibility","url":"https://scikit-learn.org/stable/model_persistence.html"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: The model file exists, but loading fails","scenario":"The artifact digest is correct and /readyz is green. The serving image was rebuilt with a different scikit-learn pin. Repair the fictional build-contract excerpt to reproduce the approved artifact environment; this JSON is an exercise input, not a pip manifest.","evidence":"10:00:00 deploy new image model-api:build-43\n10:00:20 readiness /readyz=200; model.joblib exists\n10:01:00 synthetic predict /run=503\n10:01:05 isolated trusted-artifact reproduction: InconsistentVersionWarning\n10:01:06 reproduction: model deserialization failed under runtime dependency set\n10:01:10 diagnostics checksum_matches=true build_sklearn=1.9.1 runtime_sklearn=1.8.0\n10:01:11 provenance approved; OPA same_tenant=true cross_tenant=false\n10:02:00 previous image: same artifact; scikit-learn=1.9.1; synthetic prediction passes","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"hash","text":"Edit the manifest checksum to whatever is deployed.","feedback":"The checksum already matches; changing provenance does not repair compatibility.","correct":false},{"id":"file","text":"model.joblib exists after restart.","feedback":"The old readiness check already proved only that.","correct":false},{"id":"verify","text":"A trusted rebuilt image matches the recorded environment and passes cold-start prediction and negative-input tests on every replica.","feedback":"Correct: restore a compatible immutable build and test the actual model path.","correct":true}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Reproduce only trusted artifacts: The same artifact works in the previous locked environment and fails in the rebuilt one. Do not unpickle unknown artifacts while investigating.\n\nRebuild or restore a compatible immutable image: Restore the recorded version in the build inputs, resolve the full dependency lock and repeat build/scan/review. Do not pip-install a fix into running Pods.\n\nTest actual inference: Verify cold load, valid predictions, invalid requests and per-replica identity. Add startup validation so file existence cannot mask this class of failure.","sources":[{"title":"scikit-learn: model persistence and compatibility","url":"https://scikit-learn.org/stable/model_persistence.html"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"Reproducible model promotion","scenario":"A scikit-learn model is registered in MLflow. The serving container bakes the model at build time and must reproduce predictions after promotion.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"2","text":"Assume changing the champion alias hot-reloads every existing container.","feedback":"This serving architecture baked the model into the image; alias reassignment does not replace its bytes.","correct":false},{"id":"3","text":"Install unpinned latest dependencies each time a serving Pod starts.","feedback":"Uncontrolled environment changes undermine reproducibility and can break deserialization.","correct":false},{"id":"0","text":"Resolve the approved registry version during the build and record model checksum, signature and dependency lock.","feedback":"The running image needs an immutable model identity and compatible environment.","correct":true},{"id":"1","text":"Test the actual serving image against input contracts and representative golden examples.","feedback":"Training evaluation alone misses packaging and feature-interface defects.","correct":true}],"writing":"Trace training → registry → image → deployment. Identify which changes require a new image.","model":"Record data lineage, run ID, model version, signature and environment. Resolve the approved model into an immutable image, test serialization and inference there, and promote that image with its evidence. An alias can identify a candidate, but this deployment requires a new build and rollout to change a baked artifact.","sources":[{"title":"MLflow documentation","url":"https://mlflow.org/docs/latest/"},{"title":"scikit-learn documentation","url":"https://scikit-learn.org/stable/user_guide.html"},{"title":"MLflow registry workflows","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/"}]},{"id":"operations","area":"operations","kind":"multi","title":"Monitoring beyond uptime","scenario":"The model returns HTTP 200, but approved business outcomes deteriorate. Labels arrive seven days after predictions.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"3","text":"Treat HTTP success rate as sufficient evidence of prediction quality.","feedback":"Transport success says nothing about prediction correctness.","correct":false},{"id":"0","text":"Monitor schema and feature distribution immediately, then join delayed labels to prediction IDs for quality assessment.","feedback":"Proxy signals help early detection while delayed labels establish outcome quality.","correct":true},{"id":"1","text":"Define a rollback or fallback policy using validated outcomes, affected cohorts and business cost.","feedback":"Operational action should reflect measured harm and a known safe alternative.","correct":true},{"id":"2","text":"Retrain and promote automatically on every detected input drift without evaluation.","feedback":"Drift does not prove that a new model will perform better.","correct":false}],"writing":"Describe immediate versus delayed signals, how labels are joined, and when retraining is justified.","model":"Instrument schema failures and feature shifts with versioned prediction identifiers. Join labels when available, evaluate cohort metrics and calibration, and account for selection bias in observed labels. Investigate drift before retraining; promote only after offline and serving checks. Preserve a tested fallback and the data needed to explain the decision.","sources":[{"title":"MLflow documentation","url":"https://mlflow.org/docs/latest/"},{"title":"scikit-learn documentation","url":"https://scikit-learn.org/stable/user_guide.html"},{"title":"MLflow registry workflows","url":"https://mlflow.org/docs/latest/ml/model-registry/workflow/"},{"title":"scikit-learn: model persistence and compatibility","url":"https://scikit-learn.org/stable/model_persistence.html"}]}]},"inference":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: Retries turn a burst into an outage","scenario":"vLLM is healthy but requests pile up. A client rollout increased concurrency and retries. This client-policy JSON is an illustrative caller contract. A previous controlled test met the target at four in-flight requests and at most two attempts; preserve the existing timeout.","evidence":"10:00:00 client release: max_inflight 4 -> 64; max_attempts 2 -> 8\n10:00:30 serving /health=200; no worker restarts\n10:01:00 caller timeout rate rising; repeated request IDs appear in retry logs\n10:01:05 queue snapshot: running=16 waiting=180\n10:01:10 GPU telemetry: utilization high; no CUDA OOM or device error\n10:02:00 original arrivals=5/s; total attempts including retries=31/s\n10:03:00 earlier controlled test: inflight=4 attempts\u003c=2 met the agreed latency target","prompt":"Which explanation best fits all the evidence?","options":[{"id":"cause","text":"Retry amplification and excessive admitted concurrency overload the finite serving capacity.","feedback":"Correct: original arrival rate and total attempts diverge, while queueing rises without engine crashes.","correct":true},{"id":"dns","text":"DNS failure prevents all callers from reaching the model.","feedback":"The engine reports running and queued work; this is not an all-request DNS failure.","correct":false},{"id":"oom","text":"Host memory termination is restarting the engine.","feedback":"No restart or OOM evidence is present in this fixture.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Establish the overload loop: Requests can time out while server work continues. Repeated attempts then compete with original work and grow the queue.\n\nContain at the caller: Restore the measured concurrency and total-attempt limits through the caller’s reviewed deployment path. The capstone does not ship a gateway.","sources":[{"title":"vLLM: memory and performance tuning","url":"https://docs.vllm.ai/en/stable/configuration/optimization/"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: Retries turn a burst into an outage","scenario":"vLLM is healthy but requests pile up. A client rollout increased concurrency and retries. This client-policy JSON is an illustrative caller contract. A previous controlled test met the target at four in-flight requests and at most two attempts; preserve the existing timeout.","evidence":"10:00:00 client release: max_inflight 4 -> 64; max_attempts 2 -> 8\n10:00:30 serving /health=200; no worker restarts\n10:01:00 caller timeout rate rising; repeated request IDs appear in retry logs\n10:01:05 queue snapshot: running=16 waiting=180\n10:01:10 GPU telemetry: utilization high; no CUDA OOM or device error\n10:02:00 original arrivals=5/s; total attempts including retries=31/s\n10:03:00 earlier controlled test: inflight=4 attempts\u003c=2 met the agreed latency target","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"verify","text":"The queue drains; representative load meets latency/error targets while retries remain bounded during overload.","feedback":"Correct: test normal and overload behavior, including wasted/retried work.","correct":true},{"id":"util","text":"GPU utilization stays at 100%.","feedback":"Utilization alone does not measure user success or queue delay.","correct":false},{"id":"timeout","text":"Raise timeouts until requests stop reporting failure.","feedback":"Longer waits can hide saturation and retain more work without restoring capacity.","correct":false}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Contain at the caller: Restore the measured concurrency and total-attempt limits through the caller’s reviewed deployment path. The capstone does not ship a gateway.\n\nMeasure recovery: Compare bounded tests with the baseline and then a representative sustained workload. Twenty short requests alone are not a production capacity certification.\n\nTest the next overload: Verify admission, cancellation, deadlines and jitter. Add capacity only with measured hardware headroom and startup/routing evidence.","sources":[{"title":"vLLM: memory and performance tuning","url":"https://docs.vllm.ai/en/stable/configuration/optimization/"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"A vLLM service under mixed load","scenario":"Interactive users require p95 time to first token below 2 seconds. Batch jobs have long contexts. GPU memory is limited; the SLO is a target to validate, not an observed result.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"3","text":"Assume low GPU utilization proves there is no serving bottleneck.","feedback":"Queue policy, CPU preprocessing or memory pressure can limit throughput even when utilization is low.","correct":false},{"id":"0","text":"Benchmark input/output length distributions, concurrency and queue time on the target GPU.","feedback":"A single short prompt does not represent memory demand or tail latency.","correct":true},{"id":"1","text":"Bound admission and separate batch from interactive traffic when shared scheduling breaks the latency target.","feedback":"Capacity isolation and load shedding can protect interactive response time.","correct":true},{"id":"2","text":"Maximize batch size regardless of measured time to first token.","feedback":"Throughput and latency trade off; a larger batch can worsen user experience.","correct":false}],"writing":"Sketch admission → queue → vLLM workers. State your capacity experiment and overload behavior.","model":"Define workload distributions and measure queue time, time to first token, inter-token latency, completion latency and memory at increasing concurrency. Tune batching and memory use on supported hardware. Set finite queue and token limits, propagate deadlines and isolate batch work where required. Report both throughput and latency, including rejected requests.","sources":[{"title":"vLLM documentation","url":"https://docs.vllm.ai/en/stable/"},{"title":"Prometheus documentation","url":"https://prometheus.io/docs/introduction/overview/"},{"title":"vLLM production metrics","url":"https://docs.vllm.ai/en/stable/usage/metrics/"}]},{"id":"operations","area":"operations","kind":"multi","title":"Retry and capacity policy","scenario":"A provider slows down. Clients time out at 5 seconds and retry while the first attempts continue executing.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"0","text":"Use a shared end-to-end deadline and bounded retry budget with jitter for eligible failures.","feedback":"A retry should fit the caller deadline and avoid synchronized load amplification.","correct":true},{"id":"1","text":"Track attempts per logical request and propagate cancellation where supported.","feedback":"Logical success counts alone hide duplicate work and exhausted capacity.","correct":true},{"id":"2","text":"Retry every timeout forever because requests are reads.","feedback":"Read-only work can still consume expensive capacity and worsen overload.","correct":false},{"id":"3","text":"Report only successful request latency and omit rejections.","feedback":"This hides overload and creates a misleading view of user experience.","correct":false}],"writing":"Define retry eligibility, cancellation limitations and metrics proving the recovery.","model":"Cap concurrency and attempts, use backoff with jitter, and avoid retrying when the remaining deadline cannot cover useful work. Cancellation is best-effort across boundaries, so measure work that continues after timeout. Compare attempt rate, queue depth, rejection rate and user-level success after mitigation; add capacity only after understanding the bottleneck.","sources":[{"title":"vLLM documentation","url":"https://docs.vllm.ai/en/stable/"},{"title":"Prometheus documentation","url":"https://prometheus.io/docs/introduction/overview/"},{"title":"vLLM production metrics","url":"https://docs.vllm.ai/en/stable/usage/metrics/"},{"title":"vLLM: memory and performance tuning","url":"https://docs.vllm.ai/en/stable/configuration/optimization/"}]}]},"gpu":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: Spare GPUs, unschedulable workload","scenario":"A GKE GPU workload stays Pending. The approved model image was validated on L4, and an L4 node has one unallocated GPU. Namespace quota and taints are already verified compatible. Repair only the mistaken placement selector.","evidence":"10:00:00 scheduler: 0/3 nodes available; node(s) did not match Pod node affinity/selector\n10:00:20 node gpu-l4-1 Ready labels cloud.google.com/gke-accelerator=nvidia-l4\n10:00:21 node gpu-l4-1 allocatable nvidia.com/gpu=2; allocated requests=1\n10:00:22 workload request nvidia.com/gpu=1; quota remaining=1\n10:00:23 taint nvidia.com/gpu:NoSchedule has matching Pod toleration\n10:01:00 image compatibility record: this candidate validated on NVIDIA L4\n10:02:00 Pod phase=Pending; no container has started","prompt":"Which explanation best fits all the evidence?","options":[{"id":"cause","text":"The Pod requests an accelerator label that no eligible node provides.","feedback":"Correct: scheduler evidence and the node label isolate a placement mismatch.","correct":true},{"id":"quota","text":"The namespace has zero remaining GPU quota.","feedback":"The quota evidence explicitly shows one GPU remains available.","correct":false},{"id":"vram","text":"CUDA allocation failed while loading weights.","feedback":"The container never started. GPU memory debugging is premature.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Read scheduler evidence first: The Pod has not executed code. Verify selector, quota, taints and allocated resources before investigating CUDA.\n\nCheck compatibility before changing placement: The fixture explicitly validates L4. Removing every selector or adding broad tolerations would discard the intended hardware boundary.","sources":[{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"},{"title":"Kubernetes: Pod lifecycle","url":"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"},{"title":"vLLM: memory and performance tuning","url":"https://docs.vllm.ai/en/stable/configuration/optimization/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: Spare GPUs, unschedulable workload","scenario":"A GKE GPU workload stays Pending. The approved model image was validated on L4, and an L4 node has one unallocated GPU. Namespace quota and taints are already verified compatible. Repair only the mistaken placement selector.","evidence":"10:00:00 scheduler: 0/3 nodes available; node(s) did not match Pod node affinity/selector\n10:00:20 node gpu-l4-1 Ready labels cloud.google.com/gke-accelerator=nvidia-l4\n10:00:21 node gpu-l4-1 allocatable nvidia.com/gpu=2; allocated requests=1\n10:00:22 workload request nvidia.com/gpu=1; quota remaining=1\n10:00:23 taint nvidia.com/gpu:NoSchedule has matching Pod toleration\n10:01:00 image compatibility record: this candidate validated on NVIDIA L4\n10:02:00 Pod phase=Pending; no container has started","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"node","text":"nvidia-smi works on some cluster node.","feedback":"That does not prove the workload landed on compatible hardware or serves requests.","correct":false},{"id":"verify","text":"The Pod schedules onto the intended L4 node, loads the model and passes a real request within the startup target.","feedback":"Correct: test placement through serving, not just the scheduler stage.","correct":true},{"id":"pending","text":"The Pod object exists.","feedback":"Existence does not establish scheduling, model startup or serving.","correct":false}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Check compatibility before changing placement: The fixture explicitly validates L4. Removing every selector or adding broad tolerations would discard the intended hardware boundary.\n\nReconcile the corrected selector: Change the reviewed placement manifest and inspect the diff. An available device must still become a loaded serving replica.\n\nClose on useful service: Observe node placement, engine startup and a synthetic model response. Record time-to-ready and serving capacity for the next rollout.","sources":[{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"},{"title":"Kubernetes: Pod lifecycle","url":"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"},{"title":"vLLM: memory and performance tuning","url":"https://docs.vllm.ai/en/stable/configuration/optimization/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"A shared GPU training and serving cluster","scenario":"Two research teams run untrusted jobs while a latency-sensitive inference service uses the same cluster. Hardware capabilities differ across node pools.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"0","text":"Validate device, driver and runtime compatibility and use measured workload requirements for placement.","feedback":"A resource request alone does not establish that the software stack can run the workload.","correct":true},{"id":"1","text":"Choose dedicated nodes or supported hardware partitioning when required isolation exceeds shared execution guarantees.","feedback":"Isolation requirements must drive the sharing mechanism and its documented limits.","correct":true},{"id":"2","text":"Treat time slicing as identical to hardware memory and fault isolation.","feedback":"Shared execution does not imply dedicated memory or fault boundaries.","correct":false},{"id":"3","text":"Validate GPU performance solely using a CPU-only local Kubernetes cluster.","feedback":"A CPU cluster cannot reproduce device scheduling, driver behavior or GPU performance.","correct":false}],"writing":"Draw node pools and trust boundaries. Explain your isolation choice and the measurement required before sharing GPUs.","model":"Separate trust and latency classes, then validate driver/runtime/device compatibility. Select dedicated capacity or supported partitioning based on memory, fault and performance isolation requirements; document residual limits. Test realistic co-located workloads with device telemetry. A local CPU lab establishes only control-plane behavior.","sources":[{"title":"NVIDIA GPU Operator documentation","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/overview.html"},{"title":"NVIDIA DCGM / exporter documentation","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/getting-started.html"},{"title":"NVIDIA GPU sharing and isolation limits","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/gpu-sharing.html"}]},{"id":"operations","area":"operations","kind":"multi","title":"Safely upgrading a GPU node pool","scenario":"A driver upgrade is required. Active workloads hold expensive state, and spare GPU quota is limited.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"1","text":"Plan checkpointing, drain order and rollback with explicit spare-capacity and disruption limits.","feedback":"Scheduling constraints can make an apparently routine drain strand workloads.","correct":true},{"id":"2","text":"Upgrade all nodes simultaneously and rely on Pod restart for recovery.","feedback":"This removes fallback capacity and may destroy uncheckpointed progress.","correct":false},{"id":"3","text":"Treat an advertised GPU resource as sufficient evidence of a successful CUDA workload.","feedback":"Resource advertisement and actual execution are separate acceptance checks.","correct":false},{"id":"0","text":"Canary a compatible node with realistic GPU workloads before expanding the upgrade.","feedback":"A Ready node does not prove device initialization or model execution.","correct":true}],"writing":"Describe preflight checks, a canary gate and your plan when no replacement GPU is available.","model":"Check support matrices and quotas first. Validate one canary node with device health and an actual workload, including memory and latency checks. Checkpoint jobs where supported, drain in small batches with capacity available, and retain a tested rollback route. If capacity is insufficient, schedule an explicit maintenance window rather than claiming zero downtime.","sources":[{"title":"NVIDIA GPU Operator documentation","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/overview.html"},{"title":"NVIDIA DCGM / exporter documentation","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/getting-started.html"},{"title":"NVIDIA GPU sharing and isolation limits","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/gpu-sharing.html"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]}]},"agent":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: The second replica breaks durable approvals","scenario":"A scale change introduced intermittent SQLite errors. Both Pods mount the same RWO volume on the same node. The application uses an in-process lock and was designed for one writer; no shared database migration has been performed.","evidence":"10:00:00 deployment change: replicas 1 -> 2; strategy Recreate -> RollingUpdate\n10:00:25 workload-a and workload-b Running on node worker-1\n10:01:00 request-a approval resume started in workload-a\n10:01:00 request-b approval resume started in workload-b\n10:01:05 private diagnostic: sqlite3.OperationalError: database is locked\n10:01:10 PVC workflow-state Bound accessModes=[ReadWriteOnce]\n10:01:20 state probe: quick_check=ok; directory writable; free disk sufficient\n10:02:00 checkpoint/effect stores shared; process-local locks are independent","prompt":"Which explanation best fits all the evidence?","options":[{"id":"cause","text":"Two independent processes now write state despite a single-writer design.","feedback":"Correct: both Pods run on one node and their in-process locks cannot coordinate.","correct":true},{"id":"disk","text":"The evidence proves the volume is corrupted.","feedback":"quick_check passes and permissions/disk space are healthy; corruption is not supported.","correct":false},{"id":"rwo","text":"RWO guarantees only one Pod can write, so SQLite is irrelevant.","feedback":"RWO is a mount/access mode, not a cross-process application lock.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Identify concurrent writers: The mount is healthy, but two processes hold independent locks. A database integrity check cannot establish safe workflow concurrency.\n\nQuiesce and preserve state: Coordinate callers and GitOps, stop writers and follow OPERATIONS.md’s paired backup procedure before repair. Do not delete the PVC.","sources":[{"title":"LangGraph: interrupts and replay","url":"https://docs.langchain.com/oss/python/langgraph/interrupts"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: The second replica breaks durable approvals","scenario":"A scale change introduced intermittent SQLite errors. Both Pods mount the same RWO volume on the same node. The application uses an in-process lock and was designed for one writer; no shared database migration has been performed.","evidence":"10:00:00 deployment change: replicas 1 -> 2; strategy Recreate -> RollingUpdate\n10:00:25 workload-a and workload-b Running on node worker-1\n10:01:00 request-a approval resume started in workload-a\n10:01:00 request-b approval resume started in workload-b\n10:01:05 private diagnostic: sqlite3.OperationalError: database is locked\n10:01:10 PVC workflow-state Bound accessModes=[ReadWriteOnce]\n10:01:20 state probe: quick_check=ok; directory writable; free disk sufficient\n10:02:00 checkpoint/effect stores shared; process-local locks are independent","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"root","text":"Run both replicas as root.","feedback":"Additional privilege does not coordinate concurrent writers.","correct":false},{"id":"verify","text":"After quiescing and preserving a backup, one writer resumes and duplicate-approval/restart tests preserve the expected single simulated effect.","feedback":"Correct: validate business state and replay behavior after restoring topology.","correct":true},{"id":"delete","text":"Delete the PVC and wait for readiness.","feedback":"That discards workflow state and can lose effect history.","correct":false}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Quiesce and preserve state: Coordinate callers and GitOps, stop writers and follow OPERATIONS.md’s paired backup procedure before repair. Do not delete the PVC.\n\nRestore the intended topology: Review and reconcile replicas=1 and Recreate while keeping the same state claim/security context. Wait for the single writer.\n\nProve replay behavior: Test restart/resume, matching approval and duplicate submissions. A future horizontal scale-out requires a supported shared persistence and effect-idempotency design.","sources":[{"title":"LangGraph: interrupts and replay","url":"https://docs.langchain.com/oss/python/langgraph/interrupts"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"Crash-safe external actions","scenario":"An agent opens support tickets through an external API. It can crash after the API accepts a write but before the workflow checkpoint is saved.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"1","text":"Reconcile ambiguous outcomes with the external system before issuing another write.","feedback":"A lost response is not proof that the side effect did not occur.","correct":true},{"id":"2","text":"Replay every tool call after a crash and assume checkpointing makes effects exactly once.","feedback":"A workflow checkpoint cannot atomically commit an unrelated external API effect.","correct":false},{"id":"3","text":"Allow the language model to grant itself permission for a write.","feedback":"Authorization and approval must be enforced independently of generated text.","correct":false},{"id":"0","text":"Persist an action intent and stable idempotency key before attempting the write.","feedback":"A retried action must identify the original logical operation.","correct":true}],"writing":"Draw intent → authorization → external write → reconciliation → checkpoint. Mark the crash windows.","model":"Use durable action records, independently enforced authorization and approvals for consequential operations. Send a stable idempotency key if the provider supports it; otherwise design a deduplication or reconciliation workflow with explicit limits. Recover unknown outcomes before retrying. A checkpoint records workflow progress but does not guarantee exactly-once external effects.","sources":[{"title":"LangGraph documentation","url":"https://docs.langchain.com/oss/python/langgraph/overview"},{"title":"Model Context Protocol documentation","url":"https://modelcontextprotocol.io/docs/getting-started/intro"}]},{"id":"operations","area":"operations","kind":"multi","title":"Scaling the single-writer capstone","scenario":"The current exercise stores workflow state in a local SQLite file and intentionally runs one replica. The team now wants high availability.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"2","text":"Increase replicas to four while keeping independent local SQLite files.","feedback":"Each process would have a different view of workflow history and action ownership.","correct":false},{"id":"3","text":"Store approval decisions only in process memory to reduce latency.","feedback":"A restart would lose the authority and audit trail for consequential actions.","correct":false},{"id":"0","text":"Preserve one writer until a concurrency-safe state backend and ownership protocol are implemented and tested.","feedback":"Replica count cannot fix a state model that assumes one process.","correct":true},{"id":"1","text":"Test duplicate delivery, lease expiry and crash recovery before enabling multiple workers.","feedback":"Correctness depends on failure behavior as well as nominal throughput.","correct":true}],"writing":"Explain the migration plan, ownership mechanism and a test for duplicate external actions.","model":"Keep the current single-writer constraint explicit. Migrate state to a durable backend with transactional claims or leases and retain idempotency across workers. Test worker loss during action execution and ambiguous responses. Persist approvals with scope and expiry. Change replica count only after the new concurrency contract is demonstrated.","sources":[{"title":"LangGraph documentation","url":"https://docs.langchain.com/oss/python/langgraph/overview"},{"title":"Model Context Protocol documentation","url":"https://modelcontextprotocol.io/docs/getting-started/intro"},{"title":"LangGraph: interrupts and replay","url":"https://docs.langchain.com/oss/python/langgraph/interrupts"}]}]},"sre":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: The alert that never reaches on-call","scenario":"Prometheus shows a firing rule, but nobody receives it. For this exercise an Alertmanager already exists at alertmanager.monitoring.svc:9093; its receiver, route, credentials and network access have been independently tested. Repair the Prometheus configuration excerpt only.","evidence":"10:00:00 rule AtlasHighServerErrorRatio condition true\n10:02:00 /api/v1/alerts state=firing; rule health=ok\n10:02:10 /api/v1/alertmanagers activeAlertmanagers=[] droppedAlertmanagers=[]\n10:03:00 approved network probe from Prometheus namespace reaches Alertmanager:9093\n10:03:15 separate synthetic Alertmanager test: receiver delivery acknowledged\n10:03:20 no matching silence or inhibition; receiver credentials current\n10:04:00 workload alert still firing; no delivery attempt from this Prometheus","prompt":"Which explanation best fits all the evidence?","options":[{"id":"timer","text":"The alert is still pending its hold interval.","feedback":"The alert state is explicitly firing after the hold interval.","correct":false},{"id":"cause","text":"Prometheus has no configured Alertmanager target for notification delivery.","feedback":"Correct: rule evaluation works; the downstream target list is empty.","correct":true},{"id":"receiver","text":"Receiver credentials are expired.","feedback":"The independent acknowledged delivery test contradicts this explanation.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Confirm evaluation reached firing: Inspect rule health and timers before debugging transport. The fixture already establishes a firing rule.\n\nIdentify the missing route: An empty Alertmanager target list explains the lack of delivery attempts. Do not lower alert thresholds to solve transport.","sources":[{"title":"Prometheus: targets, rules, alerts and Alertmanager API","url":"https://prometheus.io/docs/prometheus/latest/querying/api/"},{"title":"Kubernetes: NetworkPolicy","url":"https://kubernetes.io/docs/concepts/services-networking/network-policies/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: The alert that never reaches on-call","scenario":"Prometheus shows a firing rule, but nobody receives it. For this exercise an Alertmanager already exists at alertmanager.monitoring.svc:9093; its receiver, route, credentials and network access have been independently tested. Repair the Prometheus configuration excerpt only.","evidence":"10:00:00 rule AtlasHighServerErrorRatio condition true\n10:02:00 /api/v1/alerts state=firing; rule health=ok\n10:02:10 /api/v1/alertmanagers activeAlertmanagers=[] droppedAlertmanagers=[]\n10:03:00 approved network probe from Prometheus namespace reaches Alertmanager:9093\n10:03:15 separate synthetic Alertmanager test: receiver delivery acknowledged\n10:03:20 no matching silence or inhibition; receiver credentials current\n10:04:00 workload alert still firing; no delivery attempt from this Prometheus","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"verify","text":"A controlled firing alert is delivered and acknowledged, then its resolution is received through the same route.","feedback":"Correct: establish end-to-end detection, delivery and resolution.","correct":true},{"id":"rule","text":"The rule appears in /api/v1/rules.","feedback":"This proves evaluation configuration, not notification delivery.","correct":false},{"id":"silence","text":"A broad silence eliminates alert noise.","feedback":"That prevents notifications instead of restoring the missing route.","correct":false}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Identify the missing route: An empty Alertmanager target list explains the lack of delivery attempts. Do not lower alert thresholds to solve transport.\n\nDeploy the reviewed notification configuration: Add the approved static target and validate the complete Prometheus configuration before rollout/reload. The exercise assumes egress and receiver setup already work.\n\nVerify the whole chain: Induce a controlled signal and record firing, delivery, acknowledgement and resolution times. A target being present alone is not enough.","sources":[{"title":"Prometheus: targets, rules, alerts and Alertmanager API","url":"https://prometheus.io/docs/prometheus/latest/querying/api/"},{"title":"Kubernetes: NetworkPolicy","url":"https://kubernetes.io/docs/concepts/services-networking/network-policies/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"An SLO for an AI assistant","scenario":"Users need answers within 8 seconds and a defensible quality floor. Some requests return 200 with unsupported content.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"2","text":"Count every HTTP 200 as a fully successful answer.","feedback":"A transport-level success can still be useless or harmful content.","correct":false},{"id":"3","text":"Promise an exact real-time quality score without a labeling or evaluation process.","feedback":"A quality SLI needs a defensible measurement method, coverage and uncertainty.","correct":false},{"id":"0","text":"Define eligible user journeys and measure latency, availability and quality with separate explicit denominators.","feedback":"Each signal describes a different failure mode and must have a clear population.","correct":true},{"id":"1","text":"Use a sampled, reviewed quality signal alongside fast availability and latency telemetry.","feedback":"Quality measurement often has delay and uncertainty that infrastructure metrics cannot replace.","correct":true}],"writing":"Specify SLIs, exclusions and what consumes the error budget. Describe where quality measurement is delayed.","model":"Define a user journey and eligible requests, then measure end-to-end latency and availability at the user boundary. Establish a separately calibrated quality measurement with sampling and lag. Set targets from user needs and baseline evidence; record exclusions. Pair fast burn alerts with slower quality review and a documented mitigation policy.","sources":[{"title":"Prometheus documentation","url":"https://prometheus.io/docs/introduction/overview/"},{"title":"OpenTelemetry documentation","url":"https://opentelemetry.io/docs/what-is-opentelemetry/"}]},{"id":"operations","area":"operations","kind":"multi","title":"From metrics to an actionable page","scenario":"Prometheus evaluates a firing rule but nobody receives a page. The on-call team also has too many unactionable alerts.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"3","text":"Put an unbounded user or request identifier on every metrics label.","feedback":"High-cardinality labels can overload telemetry storage and queries.","correct":false},{"id":"0","text":"Test the complete route from rule evaluation through receiver delivery and acknowledgement.","feedback":"A firing rule alone does not prove notification delivery.","correct":true},{"id":"1","text":"Page on actionable user impact with a runbook, owner and meaningful grouping.","feedback":"A page should trigger a defined response and avoid redundant noise.","correct":true},{"id":"2","text":"Add more dashboard panels and assume they replace notification testing.","feedback":"Dashboards do not validate a delivery path or wake the owner.","correct":false}],"writing":"Draw the alert delivery chain and name the evidence you need at every hop.","model":"Verify rule evaluation, Alertmanager discovery, grouping/inhibition, receiver configuration and actual delivery to the intended owner. Use a controlled notification drill and acknowledgement record. Tie pages to user impact and a runbook; keep investigative details in traces or logs rather than unbounded metric labels.","sources":[{"title":"Prometheus documentation","url":"https://prometheus.io/docs/introduction/overview/"},{"title":"OpenTelemetry documentation","url":"https://opentelemetry.io/docs/what-is-opentelemetry/"},{"title":"Prometheus: targets, rules, alerts and Alertmanager API","url":"https://prometheus.io/docs/prometheus/latest/querying/api/"}]}]},"security":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: The policy on disk is not the policy in use","scenario":"A ConfigMap revokes a synthetic action, but OPA still permits it. The file has propagated and policy syntax tests pass. For this challenge the chosen delivery strategy is OPA file watching; change only the startup arguments to enable it.","evidence":"10:00:00 ConfigMap/policy updated to reviewed revocation revision p18\n10:01:00 mounted file digest on both Pods equals reviewed p18 digest\n10:01:05 isolated OPA policy tests for p18 pass\n10:01:10 running OPA decision: synthetic revoked action allowed=true\n10:01:15 current args: run --server --addr=127.0.0.1:8181 /policy/policy.rego\n10:02:00 unchanged Pod template; no rollout occurred\n10:02:30 isolated new process with same file: revoked action allowed=false","prompt":"Which explanation best fits all the evidence?","options":[{"id":"cause","text":"OPA loaded the original file and has no configured watch/reload mechanism.","feedback":"Correct: a new process denies while the existing process retains the old decision.","correct":true},{"id":"syntax","text":"The revised policy cannot compile.","feedback":"Isolated policy tests and a fresh process using the same file both pass.","correct":false},{"id":"file","text":"The ConfigMap file has not reached the containers.","feedback":"Mounted hashes already match p18 on both Pods.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Test the running decision: File hashes establish delivery, not in-memory policy. Compare actual decisions across replicas.\n\nConfigure the chosen reload mechanism: Add --watch to this fixture’s startup arguments. In production choose and validate watching, bundles or checksum-driven rollout as an explicit policy-distribution design.","sources":[{"title":"OPA: CLI flags and file watching","url":"https://www.openpolicyagent.org/docs/cli"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: The policy on disk is not the policy in use","scenario":"A ConfigMap revokes a synthetic action, but OPA still permits it. The file has propagated and policy syntax tests pass. For this challenge the chosen delivery strategy is OPA file watching; change only the startup arguments to enable it.","evidence":"10:00:00 ConfigMap/policy updated to reviewed revocation revision p18\n10:01:00 mounted file digest on both Pods equals reviewed p18 digest\n10:01:05 isolated OPA policy tests for p18 pass\n10:01:10 running OPA decision: synthetic revoked action allowed=true\n10:01:15 current args: run --server --addr=127.0.0.1:8181 /policy/policy.rego\n10:02:00 unchanged Pod template; no rollout occurred\n10:02:30 isolated new process with same file: revoked action allowed=false","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"verify","text":"Every replica denies the revoked action, allows intended actions, and a second reviewed update also changes loaded decisions.","feedback":"Correct: test behavior and repeatable convergence, not only file delivery.","correct":true},{"id":"open","text":"Disable authorization until the configuration converges.","feedback":"That bypasses the control being restored.","correct":false},{"id":"hash","text":"The mounted file hash matches the reviewed hash.","feedback":"That is already true and does not prove the in-memory decision changed.","correct":false}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Configure the chosen reload mechanism: Add --watch to this fixture’s startup arguments. In production choose and validate watching, bundles or checksum-driven rollout as an explicit policy-distribution design.\n\nRoll out the argument change: Changing the Pod template starts replacement processes. Coordinate urgent revocation with traffic restriction if mixed-policy replicas are unacceptable.\n\nVerify policy convergence: Test allow and deny cases on every new Pod and another controlled revision. Confirm rollback never restores revoked access accidentally.","sources":[{"title":"OPA: CLI flags and file watching","url":"https://www.openpolicyagent.org/docs/cli"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"A tool-using assistant with hostile documents","scenario":"A retrieved document tells the assistant to export customer records. The model has access to a tool gateway.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"3","text":"Give the agent a shared administrator token to avoid tool errors.","feedback":"Broad shared credentials increase blast radius and destroy useful attribution.","correct":false},{"id":"0","text":"Authorize every tool action using trusted caller identity, scoped capabilities and validated arguments.","feedback":"Retrieved content cannot grant authority to act.","correct":true},{"id":"1","text":"Treat retrieved content as untrusted and require independent approval for sensitive writes.","feedback":"Prompt instructions are not a replacement for an enforced boundary.","correct":true},{"id":"2","text":"Use a stronger system prompt as the sole barrier against data export.","feedback":"Model behavior can be influenced by untrusted input; a prompt is not an authorization boundary.","correct":false}],"writing":"Mark the trust boundaries from retrieval to model to tool execution, and define one denied-action test.","model":"Separate instructions from untrusted retrieved data, but assume the model can still request a forbidden action. Enforce identity, tenant scope, argument schemas, allowlists and least privilege at the tool boundary. Require durable approvals for consequential actions, redact audit data and exercise adversarial tests. Record residual risk and operational ownership.","sources":[{"title":"Open Policy Agent documentation","url":"https://www.openpolicyagent.org/docs"},{"title":"Model Context Protocol documentation","url":"https://modelcontextprotocol.io/docs/getting-started/intro"}]},{"id":"operations","area":"operations","kind":"multi","title":"Policy release and evidence","scenario":"A policy service loads an authorization file at startup. A reviewed ConfigMap change reaches the filesystem, but decisions still follow the old policy.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"0","text":"Verify the policy actually active in the process and use its supported reload or rollout mechanism.","feedback":"Updated file bytes do not prove that the evaluator has loaded them.","correct":true},{"id":"1","text":"Release policies with allow and deny fixtures, a revision identifier and rollback evidence.","feedback":"Both permitted actions and preserved restrictions matter.","correct":true},{"id":"2","text":"Approve the change solely because the ConfigMap resource version increased.","feedback":"Control-plane state is not proof of runtime policy state.","correct":false},{"id":"3","text":"Temporarily allow every action until the policy service is repaired.","feedback":"Fail-open behavior can turn a deployment defect into an authorization incident.","correct":false}],"writing":"Design a release gate that detects a stale evaluator before traffic is expanded.","model":"Version the policy and validate syntax plus positive and negative fixtures. Use the documented reload or controlled rollout mechanism, then query synthetic decisions against the running evaluator and record its revision. Keep a known previous policy and preserve the fail-closed boundary during recovery. Avoid logging credentials or customer data as test evidence.","sources":[{"title":"Open Policy Agent documentation","url":"https://www.openpolicyagent.org/docs"},{"title":"Model Context Protocol documentation","url":"https://modelcontextprotocol.io/docs/getting-started/intro"},{"title":"OPA: CLI flags and file watching","url":"https://www.openpolicyagent.org/docs/cli"}]}]},"rag":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: RLS exists, but a tenant sees another tenant’s rows","scenario":"An alpha probe sees beta rows after a role-management change. The table uses FORCE RLS, the transaction-local tenant setting is correct, and the runtime role inherits SELECT from atlas_query. Repair the fictional role-IaC excerpt without altering policy or disabling TLS.","evidence":"10:00:00 role change applied to atlas_runtime\n10:01:00 runtime probe current_user=atlas_runtime rolsuper=true rolbypassrls=true\n10:01:01 atlas_docs owner=atlas_migrator relrowsecurity=true relforcerowsecurity=true\n10:01:02 transaction context atlas.tenant=alpha\n10:01:03 synthetic visibility counts: alpha=2 beta=1\n10:01:04 policy predicate: tenant=current_setting('atlas.tenant',true)\n10:02:00 database connection sslmode=verify-full; runtime inherits atlas_query SELECT","prompt":"Which explanation best fits all the evidence?","options":[{"id":"tenant","text":"The application forgot to set tenant context.","feedback":"The captured transaction context is alpha; inspect the role privileges instead.","correct":false},{"id":"cause","text":"The actual connected role bypasses row security despite FORCE RLS.","feedback":"Correct: both privileged role flags undermine the intended runtime boundary.","correct":true},{"id":"owner","text":"Only table ownership explains the bypass.","feedback":"The runtime is not the table owner; FORCE RLS is also enabled.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Contain possible disclosure: Stop affected access, preserve private audit metadata and follow the access-incident process. Use synthetic counts, not exported tenant documents, to diagnose.\n\nCorrect runtime privilege through its owner: The database owner should remove both bypass privileges through the reviewed role migration. Preserve the minimum query membership.","sources":[{"title":"PostgreSQL: row security and bypass roles","url":"https://www.postgresql.org/docs/current/ddl-rowsecurity.html"},{"title":"Kubernetes: Secret propagation","url":"https://kubernetes.io/docs/concepts/configuration/secret/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: RLS exists, but a tenant sees another tenant’s rows","scenario":"An alpha probe sees beta rows after a role-management change. The table uses FORCE RLS, the transaction-local tenant setting is correct, and the runtime role inherits SELECT from atlas_query. Repair the fictional role-IaC excerpt without altering policy or disabling TLS.","evidence":"10:00:00 role change applied to atlas_runtime\n10:01:00 runtime probe current_user=atlas_runtime rolsuper=true rolbypassrls=true\n10:01:01 atlas_docs owner=atlas_migrator relrowsecurity=true relforcerowsecurity=true\n10:01:02 transaction context atlas.tenant=alpha\n10:01:03 synthetic visibility counts: alpha=2 beta=1\n10:01:04 policy predicate: tenant=current_setting('atlas.tenant',true)\n10:02:00 database connection sslmode=verify-full; runtime inherits atlas_query SELECT","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"tls","text":"Turn off TLS so database errors are easier to inspect.","feedback":"TLS is healthy and unrelated to this privilege bypass.","correct":false},{"id":"sql","text":"The CREATE POLICY statement exists in a migration file.","feedback":"That does not prove the connected runtime identity is constrained.","correct":false},{"id":"verify","text":"The real runtime role has neither bypass privilege; alpha/beta negative tests remain isolated across connection reuse and restart.","feedback":"Correct: validate the effective identity and behavior, not merely policy declarations.","correct":true}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Correct runtime privilege through its owner: The database owner should remove both bypass privileges through the reviewed role migration. Preserve the minimum query membership.\n\nRe-establish the intended identity: Check credential references and restart/reconnect as needed; rotating an app Secret alone does not revoke an exposed database credential.\n\nTest isolation across reuse: Use synthetic alpha and beta rows with fresh and reused connections, missing tenant context and request failures. Confirm policy, identity and TLS remain correct.","sources":[{"title":"PostgreSQL: row security and bypass roles","url":"https://www.postgresql.org/docs/current/ddl-rowsecurity.html"},{"title":"Kubernetes: Secret propagation","url":"https://kubernetes.io/docs/concepts/configuration/secret/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"Tenant-isolated retrieval","scenario":"A document assistant uses PostgreSQL and pgvector. Two tenants have similar documents. A ranking improvement must not expose another tenant’s text.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"0","text":"Apply trusted tenant authorization before retrieved content reaches the model and validate cross-tenant denial.","feedback":"Filtering output text after generation cannot undo an upstream disclosure.","correct":true},{"id":"1","text":"Use a least-privilege application role and explicitly test row-security behavior with that role.","feedback":"Owner, superuser and BYPASSRLS privileges can bypass intended protection.","correct":true},{"id":"2","text":"Retrieve globally and ask the model to hide documents from other tenants.","feedback":"The data has already crossed the security boundary.","correct":false},{"id":"3","text":"Assume enabling RLS constrains a superuser connection.","feedback":"PostgreSQL superusers and BYPASSRLS roles bypass row security.","correct":false}],"writing":"Sketch identity → retrieval scope → ranking → context → response, with a test at the trust boundary.","model":"Derive tenant scope from authenticated identity and enforce access in retrieval using a restricted application role. Test positive and cross-tenant negative cases through the actual connection role. Keep rankers and caches tenant-aware, enforce revocation/deletion behavior and prevent unauthorized content from entering prompts or logs.","sources":[{"title":"PostgreSQL + pgvector documentation","url":"https://github.com/pgvector/pgvector"},{"title":"PostgreSQL row security","url":"https://www.postgresql.org/docs/current/ddl-rowsecurity.html"}]},{"id":"operations","area":"operations","kind":"multi","title":"Evaluating retrieval changes","scenario":"A new embedding model improves one demo query but customers frequently search exact product identifiers and recently updated manuals.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"1","text":"Track retrieval relevance, answer grounding and freshness as distinct checks.","feedback":"Good ranking does not prove the answer is grounded or current.","correct":true},{"id":"2","text":"Choose the largest embedding model solely from its generic leaderboard rank.","feedback":"A generic benchmark does not establish fit for this corpus, latency or cost.","correct":false},{"id":"3","text":"Reuse cached answers after permission or document updates without an invalidation policy.","feedback":"Stale caches can preserve incorrect or newly unauthorized content.","correct":false},{"id":"0","text":"Compare lexical, vector and hybrid approaches on the same judged query set and workload.","feedback":"Exact identifiers and semantic paraphrases may favor different retrieval methods.","correct":true}],"writing":"Define a benchmark, a freshness test and the migration/rollback plan for an embedding change.","model":"Build judged queries covering identifiers, paraphrases, languages, permission boundaries and recent changes. Compare retrieval metrics and answer grounding with fixed datasets. Version embedding and chunking configuration, reindex safely, and retain a rollback strategy. Test cache invalidation on document and permission changes, measuring latency and cost as well as relevance.","sources":[{"title":"PostgreSQL + pgvector documentation","url":"https://github.com/pgvector/pgvector"},{"title":"PostgreSQL row security","url":"https://www.postgresql.org/docs/current/ddl-rowsecurity.html"},{"title":"PostgreSQL: row security and bypass roles","url":"https://www.postgresql.org/docs/current/ddl-rowsecurity.html"}]}]},"finops":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: The collector never gets past STS","scenario":"The EKS collector stopped after moving into atlas-finops-staging. The role annotation, OIDC provider, audience and network path are already verified. Account and provider IDs below are synthetic. Repair the exact trust subject; do not broaden it with a wildcard.","evidence":"10:00:00 Job collector-101 starts in namespace atlas-finops-staging\n10:00:01 serviceAccountName=collector; expected IRSA role annotation present\n10:00:02 SDK safe diagnostic: STS AssumeRoleWithWebIdentity AccessDenied\n10:00:03 projected token metadata: sub=system:serviceaccount:atlas-finops-staging:collector\n10:00:04 trust policy subject=system:serviceaccount:default:collector\n10:00:05 audience sts.amazonaws.com and OIDC provider match\n10:01:00 Cost Explorer calls attempted=0; S3 writes attempted=0\n10:02:00 no static key or node-identity fallback configured","prompt":"Which explanation best fits all the evidence?","options":[{"id":"s3","text":"The report prefix denies s3:PutObject.","feedback":"No S3 request was attempted; the failure occurs earlier.","correct":false},{"id":"cause","text":"The trust policy expects the old namespace in its service-account subject.","feedback":"Correct: the exact token subject and allowed subject differ.","correct":true},{"id":"ce","text":"Cost Explorer rejected the billing date range.","feedback":"The collector has not obtained credentials or attempted Cost Explorer.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Locate the failing identity stage: No Cost Explorer or S3 call occurred. Inspect the service account, token metadata and safe STS error without printing tokens.\n\nRepair the narrow trust condition: Update only the subject in reviewed IAM IaC. Keep the correct provider and audience, and avoid wildcard service-account access.","sources":[{"title":"AWS: IAM roles for service accounts","url":"https://docs.aws.amazon.com/eks/latest/userguide/iam-roles-for-service-accounts.html"},{"title":"AWS: Cost Explorer API","url":"https://docs.aws.amazon.com/cost-management/latest/userguide/ce-api.html"},{"title":"Kubernetes: CronJob scheduling behavior","url":"https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: The collector never gets past STS","scenario":"The EKS collector stopped after moving into atlas-finops-staging. The role annotation, OIDC provider, audience and network path are already verified. Account and provider IDs below are synthetic. Repair the exact trust subject; do not broaden it with a wildcard.","evidence":"10:00:00 Job collector-101 starts in namespace atlas-finops-staging\n10:00:01 serviceAccountName=collector; expected IRSA role annotation present\n10:00:02 SDK safe diagnostic: STS AssumeRoleWithWebIdentity AccessDenied\n10:00:03 projected token metadata: sub=system:serviceaccount:atlas-finops-staging:collector\n10:00:04 trust policy subject=system:serviceaccount:default:collector\n10:00:05 audience sts.amazonaws.com and OIDC provider match\n10:01:00 Cost Explorer calls attempted=0; S3 writes attempted=0\n10:02:00 no static key or node-identity fallback configured","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"laptop","text":"Your laptop’s aws sts get-caller-identity succeeds.","feedback":"That proves the operator identity, not the Pod’s web-identity role.","correct":false},{"id":"admin","text":"Attach AdministratorAccess until the job succeeds.","feedback":"Broader permissions do not repair the exact trust condition and introduce unnecessary privilege.","correct":false},{"id":"verify","text":"A new Pod assumes the intended role, reads the expected period and writes one report under the scoped prefix.","feedback":"Correct: test both assumption and the subsequent least-privilege API stages.","correct":true}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Repair the narrow trust condition: Update only the subject in reviewed IAM IaC. Keep the correct provider and audience, and avoid wildcard service-account access.\n\nRun one controlled retry: Allow propagation, then run a new Job under the service account. This performs real billable reads and a private S3 write if executed in your account.\n\nVerify identity and report provenance: Inspect the safe assumed-role identity and successful report key/period; then verify the next scheduled run. Use a separate authorized reader for S3 inspection.","sources":[{"title":"AWS: IAM roles for service accounts","url":"https://docs.aws.amazon.com/eks/latest/userguide/iam-roles-for-service-accounts.html"},{"title":"AWS: Cost Explorer API","url":"https://docs.aws.amazon.com/cost-management/latest/userguide/ce-api.html"},{"title":"Kubernetes: CronJob scheduling behavior","url":"https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"Cost per useful outcome","scenario":"Request volume is flat but the bill doubles. Requests can retry, use different models and fail after consuming tokens. Some capacity is idle.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"1","text":"Separate direct usage from idle/shared allocation and state the successful-outcome denominator.","feedback":"An opaque allocation or denominator can make a unit-cost comparison misleading.","correct":true},{"id":"2","text":"Estimate total spend as request count times a fixed token assumption.","feedback":"Context, output length, route and retries can change independently of request count.","correct":false},{"id":"3","text":"Discard failed-request usage because it produced no useful answer.","feedback":"Failed work can still consume billable tokens and infrastructure.","correct":false},{"id":"0","text":"Join logical requests to all attempts and model usage, including failed and retried work.","feedback":"Billing follows consumed resources, not only successful final responses.","correct":true}],"writing":"Draw the usage ledger and reconciliation flow. Define cost per successful outcome with its limitations.","model":"Record request and attempt IDs, route/model versions, token or resource usage and outcome labels without sensitive prompts. Reconcile aggregates with provider billing, accounting for delays and allocation rules. Explain idle capacity separately and define the denominator precisely. Investigate length, route, retries and cache mix before attributing the increase to price.","sources":[{"title":"OpenCost documentation","url":"https://opencost.io/docs/"},{"title":"AWS Budgets and notification delay","url":"https://docs.aws.amazon.com/cost-management/latest/userguide/budgets-managing-costs.html"}]},{"id":"operations","area":"operations","kind":"multi","title":"Cutting spend without losing quality","scenario":"A proposed cheaper route saves 30% in a synthetic sample. Critical customers require the existing quality and latency targets.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"2","text":"Switch every request to the cheapest model without testing task success.","feedback":"Lower unit price can increase retries, failures or total cost per useful outcome.","correct":false},{"id":"3","text":"Set budget alerts and assume they enforce a hard real-time spending cap.","feedback":"An alert is a notification; enforcement requires a separate control and can have delay.","correct":false},{"id":"0","text":"Evaluate route changes against quality, latency and cost by customer/task slice.","feedback":"An aggregate saving can hide expensive regressions in a critical cohort.","correct":true},{"id":"1","text":"Canary with budget alerts, usage attribution and a quality-triggered rollback.","feedback":"A measured rollout makes savings and regressions observable.","correct":true}],"writing":"Propose a cost experiment, guardrails and the signal that would reverse the change.","model":"Baseline spend and quality by task, then test smaller models, caching or batching only where requirements permit. Include failed attempts, cache behavior and latency in unit economics. Canary the route and use explicit rollback thresholds for critical slices. Combine alerts with tested admission controls where hard limits are required; document delayed billing and enforcement limits.","sources":[{"title":"OpenCost documentation","url":"https://opencost.io/docs/"},{"title":"AWS Budgets and notification delay","url":"https://docs.aws.amazon.com/cost-management/latest/userguide/budgets-managing-costs.html"},{"title":"AWS: IAM roles for service accounts","url":"https://docs.aws.amazon.com/eks/latest/userguide/iam-roles-for-service-accounts.html"}]}]},"devplatform":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: The hotfix that keeps reverting","scenario":"A tested previous image restores service when patched live, but Argo CD later restores the faulty candidate. Edit the watched Git manifest excerpt. Image digests are synthetic; the previous image is explicitly compatible with current data and has passed recovery checks.","evidence":"10:00:00 Git revision bad-44 selects ghcr.io/example/atlas@sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\n10:00:20 candidate smoke /run=503\n10:01:00 operator live repair selects ghcr.io/example/atlas@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n10:01:20 known-good smoke /run=200; data compatibility verified\n10:02:00 Argo automated self-heal enabled; watched branch=staging\n10:02:05 controller reconciles watched bad-44; live image returns to digest b...\n10:02:30 smoke /run=503 again; no matching Git repair was merged","prompt":"Which explanation best fits all the evidence?","options":[{"id":"cause","text":"Self-heal restores the faulty image because Git still declares it as desired state.","feedback":"Correct: the controller is enforcing the uncorrected watched revision.","correct":true},{"id":"health","text":"Readiness cannot distinguish a running process from a healthy service.","feedback":"That can be a general weakness, but it does not explain the image changing back.","correct":false},{"id":"cache","text":"The registry randomly changes immutable digest contents.","feedback":"The desired and live digests explicitly switch with reconciliation; no registry mutation evidence is given.","correct":false}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Identify the controller’s source of truth: Read Application repository/branch, desired revision and diff before fighting reconciliation.\n\nMake the repair durable: Revert the specific faulty deployment commit or merge a reviewed fix selecting the known-good digest. The fixture confirms data compatibility; real incidents require this check.","sources":[{"title":"Argo CD: automated sync and self-healing","url":"https://argo-cd.readthedocs.io/en/stable/user-guide/auto_sync/"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: The hotfix that keeps reverting","scenario":"A tested previous image restores service when patched live, but Argo CD later restores the faulty candidate. Edit the watched Git manifest excerpt. Image digests are synthetic; the previous image is explicitly compatible with current data and has passed recovery checks.","evidence":"10:00:00 Git revision bad-44 selects ghcr.io/example/atlas@sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\n10:00:20 candidate smoke /run=503\n10:01:00 operator live repair selects ghcr.io/example/atlas@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n10:01:20 known-good smoke /run=200; data compatibility verified\n10:02:00 Argo automated self-heal enabled; watched branch=staging\n10:02:05 controller reconciles watched bad-44; live image returns to digest b...\n10:02:30 smoke /run=503 again; no matching Git repair was merged","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"pause","text":"Disable automation forever.","feedback":"That abandons reconciliation without repairing the source of truth.","correct":false},{"id":"verify","text":"The reviewed Git revision and live image agree, checks pass, and another self-heal cycle preserves the repair.","feedback":"Correct: establish durable convergence and restored automation.","correct":true},{"id":"patch","text":"One manual patch returns a successful request.","feedback":"The fixture already shows that success is temporary.","correct":false}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Make the repair durable: Revert the specific faulty deployment commit or merge a reviewed fix selecting the known-good digest. The fixture confirms data compatibility; real incidents require this check.\n\nReconcile deliberately: If emergency containment required a pause, inspect the merged diff, sync and wait for health before restoring automatic policy.\n\nObserve another reconciliation: Confirm expected digest and functional/security checks remain stable after self-heal runs. Record any temporary pause and its closure.","sources":[{"title":"Argo CD: automated sync and self-healing","url":"https://argo-cd.readthedocs.io/en/stable/user-guide/auto_sync/"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"A useful golden path","scenario":"Six teams deploy similar AI services with inconsistent CI, ownership and operational practices. The team proposes a portal.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"2","text":"Treat a catalog page alone as a complete production platform.","feedback":"Discovery does not implement build, delivery, identity or operation.","correct":false},{"id":"3","text":"Hide required security and ownership decisions behind an undocumented template.","feedback":"Teams cannot safely operate or extend a capability whose responsibilities are unclear.","correct":false},{"id":"0","text":"Ship a maintained template with CI checks, workload identity, ownership and a runnable local example.","feedback":"A platform capability needs a supported delivery and operating contract.","correct":true},{"id":"1","text":"Offer documented extension points and measure adoption and time to first safe deployment.","feedback":"Useful standardization needs feedback and a supported escape path.","correct":true}],"writing":"Draw developer request → template → CI → deployment → ownership/observability. Define the platform/team boundary.","model":"Start with a maintained template that produces an owned, observable service and verified delivery evidence. Document interfaces, secure defaults, exception handling and responsibility for upgrades. Add a catalog when discovery needs it. Measure user outcomes, migration burden and support load; keep extension points explicit rather than forcing every workload into one shape.","sources":[{"title":"Backstage documentation","url":"https://backstage.io/docs/overview/what-is-backstage/"},{"title":"GitHub Actions documentation","url":"https://docs.github.com/en/actions/get-started/understand-github-actions"}]},{"id":"operations","area":"operations","kind":"multi","title":"GitOps during an incident","scenario":"Argo CD self-healing is enabled. An operator patches an image to restore service, but reconciliation changes it back.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"3","text":"Disable all audit trails to speed up emergency changes.","feedback":"Incident changes need attribution and reconciliation evidence.","correct":false},{"id":"0","text":"Coordinate incident mitigation with the controller and commit the desired recovery state to the watched source.","feedback":"The durable correction must agree with the reconciler’s desired state.","correct":true},{"id":"1","text":"Verify both the running image digest and sync/health after recovery, then restore normal reconciliation.","feedback":"A successful API patch is not evidence that the intended state will persist.","correct":true},{"id":"2","text":"Keep repeating the same live patch indefinitely while self-healing is enabled.","feedback":"The controller will continue restoring the tracked desired state.","correct":false}],"writing":"Describe the source of truth, emergency change procedure and proof that the fix survives another sync.","model":"Identify the watched repository, revision and controller behavior. Use the documented emergency process, coordinate reconciliation and change the desired state through a reviewed commit. Verify live digest, caller behavior and controller sync after recovery. Restore normal automation and record any temporary deviation so the next sync cannot silently revert the repair.","sources":[{"title":"Backstage documentation","url":"https://backstage.io/docs/overview/what-is-backstage/"},{"title":"GitHub Actions documentation","url":"https://docs.github.com/en/actions/get-started/understand-github-actions"},{"title":"Argo CD: automated sync and self-healing","url":"https://argo-cd.readthedocs.io/en/stable/user-guide/auto_sync/"}]}]},"solutions":{"revision":1,"questions":[{"id":"diagnosis","area":"diagnosis","kind":"single","title":"Diagnose: Valid JSON, wrong prediction","scenario":"A new client still gets HTTP 200 but its golden predictions changed. The model and preprocessing are unchanged. Repair the client feature-order contract so named inputs become the same array used in training; this is an illustrative adapter configuration.","evidence":"10:00:00 new client adapter released; server image and artifact hash unchanged\n10:00:10 readiness=200; authenticated prediction requests=200\n10:01:00 approved training order: sepal_length_cm,sepal_width_cm,petal_length_cm,petal_width_cm\n10:01:10 named synthetic input: sepal_length_cm=5.1 sepal_width_cm=3.5 petal_length_cm=1.4 petal_width_cm=0.2\n10:01:11 old adapter array: [5.1,3.5,1.4,0.2]; golden class matches\n10:01:12 new adapter array: [1.4,0.2,5.1,3.5]; golden class mismatch\n10:02:00 schema accepts either four-number array; no request-shape error\n10:03:00 OPA and tenant-negative tests unchanged","prompt":"Which explanation best fits all the evidence?","options":[{"id":"auth","text":"Authentication rejects the new client.","feedback":"Authenticated requests return 200; the failure concerns the output meaning.","correct":false},{"id":"model","text":"The model weights changed unexpectedly.","feedback":"The deployed image/artifact identity is unchanged and the old adapter still passes golden cases.","correct":false},{"id":"cause","text":"The client emits semantically reordered features despite satisfying the numeric-array schema.","feedback":"Correct: a valid shape does not guarantee correct feature meaning or order.","correct":true}],"writing":"Explain the evidence chain, one alternative hypothesis and the next command you would run.","model":"Hold the model constant: A fixed artifact plus different adapter arrays isolates the client mapping. HTTP success is too narrow to detect this.\n\nRepair the semantic contract: Restore the training feature order while retaining centimetre units and strict validation. Do not guess units or silently accept extra fields.","sources":[{"title":"scikit-learn: model persistence and compatibility","url":"https://scikit-learn.org/stable/model_persistence.html"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"recovery","area":"recovery","kind":"single","title":"Recover: Valid JSON, wrong prediction","scenario":"A new client still gets HTTP 200 but its golden predictions changed. The model and preprocessing are unchanged. Repair the client feature-order contract so named inputs become the same array used in training; this is an illustrative adapter configuration.","evidence":"10:00:00 new client adapter released; server image and artifact hash unchanged\n10:00:10 readiness=200; authenticated prediction requests=200\n10:01:00 approved training order: sepal_length_cm,sepal_width_cm,petal_length_cm,petal_width_cm\n10:01:10 named synthetic input: sepal_length_cm=5.1 sepal_width_cm=3.5 petal_length_cm=1.4 petal_width_cm=0.2\n10:01:11 old adapter array: [5.1,3.5,1.4,0.2]; golden class matches\n10:01:12 new adapter array: [1.4,0.2,5.1,3.5]; golden class mismatch\n10:02:00 schema accepts either four-number array; no request-shape error\n10:03:00 OPA and tenant-negative tests unchanged","prompt":"Which recovery evidence is sufficient to close this incident?","options":[{"id":"loose","text":"Turn off unknown-field validation.","feedback":"Relaxing unrelated validation cannot fix feature order.","correct":false},{"id":"status","text":"All requests return 200.","feedback":"They already do, while golden predictions fail.","correct":false},{"id":"verify","text":"Golden semantic cases pass for supported client/server pairs, and malformed/unknown inputs remain rejected.","feedback":"Correct: verify meaning, compatibility and strict invalid-input behavior.","correct":true}],"writing":"Describe a safe recovery sequence, the verification boundary and one recurrence-prevention test.","model":"Repair the semantic contract: Restore the training feature order while retaining centimetre units and strict validation. Do not guess units or silently accept extra fields.\n\nTest client/server compatibility: Run golden cases, boundary values, missing/extra fields and all supported client versions. Include the specific regression payload.\n\nVerify rollout outcomes: Canary the corrected client and monitor golden/business outcomes as well as HTTP success. Version feature meanings with model/preprocessing contracts.","sources":[{"title":"scikit-learn: model persistence and compatibility","url":"https://scikit-learn.org/stable/model_persistence.html"},{"title":"Kubernetes: debug running Pods","url":"https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}]},{"id":"architecture","area":"architecture","kind":"multi","title":"Choosing an architecture from the problem","scenario":"A support team needs answers from manuals that change weekly, with citations and per-customer permissions. No evidence yet shows that a custom model is needed.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"3","text":"Choose a large agent framework before defining the user workflow.","feedback":"Tooling cannot substitute for a scoped problem and acceptance criteria.","correct":false},{"id":"0","text":"Start with an evaluated retrieval baseline that preserves permission and freshness constraints.","feedback":"The main requirement is access to changing authorized knowledge, which retrieval can directly address.","correct":true},{"id":"1","text":"Define a judged task set, failure budget and integration contract before selecting vendors.","feedback":"Requirements and evidence make architecture comparisons meaningful.","correct":true},{"id":"2","text":"Fine-tune on all customer manuals and assume that guarantees current citations and permissions.","feedback":"Training is not a reliable mechanism for document freshness, citation provenance or per-request authorization.","correct":false}],"writing":"Sketch the smallest viable architecture and explain what evidence would justify fine-tuning or agentic steps.","model":"Define the user workflow and judged cases first. Build a simple permission-aware retrieval and answer baseline with source citations and freshness handling. Compare it against requirements, including failure and human handoff. Consider fine-tuning for measured behavioral gaps or agents for a justified multi-step workflow; account for data rights, cost and operational ownership.","sources":[{"title":"MLflow documentation","url":"https://mlflow.org/docs/latest/"}]},{"id":"operations","area":"operations","kind":"multi","title":"A reliable client integration","scenario":"A numerical prediction endpoint accepts a fixed feature order. A client sends valid JSON with values in a different order. HTTP 200 masks wrong predictions.","evidence":"","prompt":"Select every decision that satisfies these constraints. Some proposals undermine the design.","options":[{"id":"0","text":"Version semantic input contracts and validate feature names, order, types and units at the boundary.","feedback":"Syntactic JSON validity is weaker than a correct prediction interface.","correct":true},{"id":"1","text":"Run client-to-service golden examples and contract tests before rollout.","feedback":"End-to-end fixtures catch mismatches that isolated server tests miss.","correct":true},{"id":"2","text":"Use status code 200 as the only acceptance criterion.","feedback":"The request can execute successfully with semantically incorrect inputs.","correct":false},{"id":"3","text":"Silently reorder or coerce unknown inputs without a documented schema.","feedback":"Hidden transformations can conceal client defects and alter predictions.","correct":false}],"writing":"Define the contract, compatibility policy and rollout test involving the actual client.","model":"Agree on named features, ordering where required, units, missing-value rules and schema version. Reject ambiguous input with actionable errors. Maintain golden client/service examples and test backward compatibility in CI. Roll out contract changes with a migration window and monitor validation failures plus outcome checks, rather than transport status alone.","sources":[{"title":"MLflow documentation","url":"https://mlflow.org/docs/latest/"},{"title":"scikit-learn: model persistence and compatibility","url":"https://scikit-learn.org/stable/model_persistence.html"}]}]}}};
